import{c as l,Z as a,Q as r,j as n,m as s,o as t}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"雨霖铃·寒蝉凄切","description":"","frontmatter":{"title":"雨霖铃·寒蝉凄切","author":"柳永","dynasty":"宋"},"headers":[],"relativePath":"books/shici/songci/6.md","filePath":"books/shici/songci/6.md"}'),u={name:"books/shici/songci/6.md"};function h(c,o,p,d,q,_){const e=a("PoemAuthor"),i=a("PoemNav");return r(),n("div",null,[o[0]||(o[0]=s('<h1 id="雨霖铃·寒蝉凄切" tabindex="-1">雨霖铃·寒蝉凄切 <a class="header-anchor" href="#雨霖铃·寒蝉凄切" aria-label="Permalink to &quot;雨霖铃·寒蝉凄切&quot;">​</a></h1><p><strong>[宋] <a href="/authors/liuyong.html">柳永</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>寒蝉凄切，对长亭晚，骤雨初歇。都门帐饮无绪，留恋处，兰舟催发。执手相看泪眼，竟无语凝噎。念去去，千里烟波，暮霭沉沉楚天阔。</p><p>多情自古伤离别，更那堪，冷落清秋节！今宵酒醒何处？杨柳岸，晓风残月。此去经年，应是良辰好景虚设。便纵有千种风情，更与何人说？</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>寒蝉：秋蝉</li><li>长亭：古代设在路边的亭舍，供行人休息，也是送别之地</li><li>都门：京城城门，指北宋都城汴京</li><li>帐饮：在郊外设帐幕宴饮饯行</li><li>无绪：没有情绪，心情不好</li><li>兰舟：船的美称</li><li>凝噎：喉咙哽咽，说不出话来</li><li>去去：越走越远</li><li>暮霭：傍晚的云雾</li><li>清秋节：凄清的秋季</li><li>经年：年复一年</li><li>风情：情意</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>秋蝉的叫声凄凉悲切，面对着长亭，正是傍晚时分，一阵急雨刚刚停歇。在京城门外设帐饯别，却没有畅饮的情绪，正在依依不舍的时候，船上的人已催着出发。握着手互相凝望，泪眼相对，竟然哽咽得说不出话来。想这一去，千里烟波浩渺，傍晚的云雾沉沉，楚地天空辽阔无边。</p><p>自古以来多情的人最伤心的是离别，更何况又逢这冷落凄凉的清秋时节！今夜酒醒之后会在何处？恐怕是在杨柳岸边，面对晓风残月。这一去长年相别，就算是遇到良辰美景，也如同虚设。纵然有千万种深情蜜意，又能向谁去诉说呢？</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首词是柳永的代表作，写离别之情，是宋词中抒写离情别绪的名篇。</p><p>上片写离别时的情景。&quot;寒蝉凄切，对长亭晚，骤雨初歇&quot;，以凄清的秋景烘托离别的氛围。&quot;都门帐饮无绪&quot;，写饯别时的心情，&quot;无绪&quot;二字概括了满腹愁思。&quot;留恋处，兰舟催发&quot;，矛盾的心理，将离别的不舍推向高潮。&quot;执手相看泪眼，竟无语凝噎&quot;，细节描写生动传神，将恋人之间难舍难分的情感刻画得淋漓尽致。&quot;念去去，千里烟波，暮霭沉沉楚天阔&quot;，由实入虚，想象别后的行程，以辽阔苍茫的景色，衬托出孤独无依的心情。</p><p>下片写别后的思念。&quot;多情自古伤离别，更那堪，冷落清秋节&quot;，将个人的离别之苦推广到普遍的人生体验。&quot;今宵酒醒何处？杨柳岸，晓风残月&quot;，设想酒醒后的情景，以凄清的景物烘托孤寂的心情，成为千古传诵的名句。&quot;此去经年&quot;以下，写别后的漫长岁月，良辰美景无人共赏，千种风情无处诉说，将离别的痛苦延伸到未来。</p><p>全词情景交融，虚实相生，将离别之情写得缠绵悱恻，动人心魄。</p>',15)),t(e,{name:"柳永",years:"约984年－约1053年",desc:"字耆卿，北宋著名词人，婉约派代表人物。其词多写都市生活和歌妓情感，语言通俗，流传极广。",link:"/authors/liuyong"}),t(i)])}const b=l(u,[["render",h]]);export{f as __pageData,b as default};
